import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/reports', extractTenant, async (req, res) => {
  try {
    const { status, date_from, date_to, sort_by, order } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, title, created_at, status, author_id 
                 FROM reports WHERE tenant_id = '${req.tenantId}'`;

    // Apply filters
    if (status) {
      query += ` AND status = '${status}'`;
    }
    if (date_from) {
      query += ` AND created_at >= '${date_from}'`;
    }
    if (date_to) {
      query += ` AND created_at <= '${date_to}'`;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'status'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 100`;

    const result = await pool.query(query);

    // Audit log
    await pool.query(
      'INSERT INTO audit_log (tenant_id, user_id, action, details, ts) VALUES ($1, $2, $3, $4, NOW())',
      [req.tenantId, req.userId, 'REPORT_SEARCH', JSON.stringify(req.query)]
    );

    return res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Delete endpoint
app.delete('/api/v2/reports/:id', extractTenant, async (req, res) => {
  const reportId = req.params.id;
  // Note: no parameterized query here either
  const check = await pool.query(
    `SELECT id FROM reports WHERE id = '${reportId}' AND tenant_id = '${req.tenantId}'`
  );
  if (check.rowCount === 0) return res.status(404).json({ error: 'Not found' });

  await pool.query(`DELETE FROM reports WHERE id = '${reportId}'`);
  return res.json({ deleted: true });
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', ts: Date.now() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Report service listening on ${process.env.PORT || 3000}`);
});
